sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', remediation_plans: [] };
  try {
    var failedChecks = JSON.parse(inputs.failed_checks);

    for (var i = 0; i < failedChecks.length; i++) {
      var check = failedChecks[i];
      var plan = {
        plugin_name: check.name,
        sys_id: check.sys_id,
        steps: [],
        priority: 'high',
        estimated_effort: 'low'
      };

      for (var b = 0; b < (check.blockers || []).length; b++) {
        var blocker = check.blockers[b];
        if (blocker.indexOf('not found') >= 0) {
          plan.steps.push('Verify plugin sys_id is correct and accessible with current credentials');
          plan.steps.push('Check if plugin was removed or renamed in recent updates');
          plan.estimated_effort = 'medium';
        } else if (blocker.indexOf('dependency') >= 0) {
          plan.steps.push('Install or update required dependency plugins first');
          plan.steps.push('Review dependency chain and upgrade in correct order');
          plan.estimated_effort = 'high';
        } else {
          plan.steps.push('Review and resolve: ' + blocker);
        }
      }

      for (var w = 0; w < (check.warnings || []).length; w++) {
        var warning = check.warnings[w];
        if (warning.indexOf('Customization') >= 0) {
          plan.steps.push('Back up customizations before proceeding');
          plan.steps.push('Review customization impact post-upgrade');
        } else if (warning.indexOf('update set') >= 0) {
          plan.steps.push('Complete or close active update sets before upgrading');
        } else if (warning.indexOf('inactive') >= 0) {
          plan.steps.push('Plugin will be activated during upgrade - verify this is acceptable');
        }
      }

      if (plan.steps.length === 0) {
        plan.steps.push('No specific remediation needed - proceed with caution');
      }

      plan.steps.push('Schedule a maintenance window for the upgrade');
      plan.steps.push('Notify stakeholders before proceeding');

      result.remediation_plans.push(plan);
    }
  } catch (e) {
    result.status = 'error';
    result.message = 'Failed to generate remediation: ' + e.message;
  }
  return result;
})(inputs);
